package com.citacloud.springboot.contacloud.app.services;import com.citacloud.springboot.contacloud.app.dto.AjusteInventarioReporteData;import com.lowagie.text.pdf.*;import com.lowagie.text.pdf.parser.PdfTextExtractor;import org.junit.jupiter.api.Test;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.stream.IntStream;import static org.assertj.core.api.Assertions.assertThat;
class AjusteInventarioPdfServiceTest{private final AjusteInventarioPdfService service=new AjusteInventarioPdfService();
 @Test void generaPdfConSaldosHistoricosYSignos()throws Exception{byte[] pdf=service.generar(data(3),ZoneId.of("America/Santo_Domingo"));assertThat(pdf).startsWith("%PDF-".getBytes(StandardCharsets.US_ASCII));assertThat(text(pdf)).contains("AJUSTE DE INVENTARIO","AJU-000125","CONFIRMADO","Almacén Principal","Sucursal Principal","-2.00","+3.00","ANTERIOR","POSTERIOR").doesNotContainIgnoringCase("ContaCloud");}
 @Test void generaMultipaginaConEncabezadoYPaginacion()throws Exception{byte[] pdf=service.generar(data(80),ZoneId.of("America/Santo_Domingo"));Path dir=Path.of("target","pdf-preview");Files.createDirectories(dir);Files.write(dir.resolve("ajuste-inventario-preview.pdf"),pdf);PdfReader r=new PdfReader(pdf);assertThat(r.getNumberOfPages()).isGreaterThan(1);PdfTextExtractor x=new PdfTextExtractor(r);for(int i=1;i<=r.getNumberOfPages();i++)assertThat(x.getTextFromPage(i)).contains("Página");r.close();}
 @Test void formateaIdentidadEmpresa(){Map<String,Object> p=AjusteInventarioPdfService.params(data(1),ZoneId.of("America/Santo_Domingo"));assertThat(p).containsEntry("companyTaxIdentification","124-54367-8").containsEntry("companyPhone","809-555-1234").containsEntry("status","CONFIRMADO");}
 private static AjusteInventarioReporteData data(int count){var ls=IntStream.rangeClosed(1,count).mapToObj(i->new AjusteInventarioReporteData.Linea(i,"Producto de inventario "+i,"Unidad","25.00",i%2==0?"+3.00":"-2.00",i%2==0?"28.00":"23.00")).toList();return new AjusteInventarioReporteData("EMPRESA DEMO, SRL","Empresa Demo Dominicana, SRL","124543678","Av. Principal #123","8095551234","correo@empresa.com",null,"AJU-000125","Confirmado",LocalDate.of(2026,10,13),"Almacén Principal","Sucursal Principal","Corrección de inventario","REVISIÓN-001","Diferencias detectadas durante revisión.",OffsetDateTime.parse("2026-10-13T20:05:00-04:00"),"María López","María López",OffsetDateTime.parse("2026-10-13T20:06:00-04:00"),ls);}
 private static String text(byte[] pdf)throws Exception{PdfReader r=new PdfReader(pdf);PdfTextExtractor x=new PdfTextExtractor(r);StringBuilder b=new StringBuilder();for(int i=1;i<=r.getNumberOfPages();i++)b.append(x.getTextFromPage(i));r.close();return b.toString();}}
